import { showPublicationSchema } from '@handmake/core';
import type { Post, ShowMediaSource, TenantConfig } from '@handmake/core';
import type { GitRepoContentStore } from '@handmake/stores';
import type { DispatchPayload } from './payload';
import { verifyMarkedMedia } from './marking';

/** Validate approved metadata before downloading; never transform marked generated bytes. */
export async function prepareShowPublication(
  payload: DispatchPayload,
  tenant: TenantConfig,
  store: GitRepoContentStore,
  source: ShowMediaSource,
) {
  const { show, media: refs } = showPublicationSchema.parse(payload.show);
  if (
    Object.keys(show.versions).length !== tenant.languages.length ||
    tenant.languages.some((lang) => !Object.hasOwn(show.versions, lang))
  )
    throw new Error('show languages must match tenant languages');
  const work = await store.readWork(tenant.id, show.workId);
  if (!work) throw new Error('show work is unavailable for tenant');
  for (const original of show.originals) {
    if (!(await store.readWorkPhoto(tenant.id, work.id, original.fileName))?.length)
      throw new Error('show original is missing from linked work');
  }
  if ((await store.readPost(tenant.id, show.id)) || (await store.readWork(tenant.id, show.id)))
    throw new Error('show id already belongs to other content');
  const ledger = await store.readLedger(tenant.id, show.id);
  if (ledger && Object.keys(ledger.channels).length)
    throw new Error('show channel copies are not supported before T46');
  const media = [];
  for (const ref of refs) {
    const data = await source.fetchMedia(ref.ref);
    const declared =
      ref.fileName === show.video.fileName
        ? show.video
        : show.images.find((image) => image.fileName === ref.fileName)!;
    await verifyMarkedMedia(
      data,
      ref.fileName === show.video.fileName ? 'video/mp4' : 'image/png',
      declared.marker,
      show.video.durationSeconds,
    );
    if (ref.fileName !== show.video.fileName && !ref.fileName.endsWith('.png'))
      throw new Error('marked show images must use PNG filenames');
    media.push({ fileName: ref.fileName, data });
  }
  const post: Post = {
    id: show.id,
    tenant: show.tenant,
    date: show.date,
    publishAt: 'now',
    type: 'free',
    channels: [],
    photos: show.images.map((image) => image.fileName),
    texts: payload.texts,
    versions: Object.fromEntries(
      Object.entries(show.versions).map(([lang, { description: _, ...version }]) => [
        lang,
        version,
      ]),
    ),
  };
  return { show, media, post, paths: [`content/shows/${show.id}`] };
}
